    public OrderService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new OrderEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(OrderRepository.class) );
		this.validator		= applicationContext.getBean(OrderValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Order
	 */
		public Order createOrder( CreateOrderCommand command ) {

		Order entity = new Order();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setOrderId( command.getOrderId() );
            entity.setOrderNumber( command.getOrderNumber() );
            entity.setPlacedDate( command.getPlacedDate() );
            entity.setSubtotal( command.getSubtotal() );
            entity.setDiscountTotal( command.getDiscountTotal() );
            entity.setShippingTotal( command.getShippingTotal() );
            entity.setTaxTotal( command.getTaxTotal() );
            entity.setGrandTotal( command.getGrandTotal() );
            entity.setShippingAddress( command.getShippingAddress() );
            entity.setBillingAddress( command.getBillingAddress() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Order {0} ", entity.toString() );

		return entity;
	}

